import torch,torch.nn.functional as F; exec("class Solution:\n    def train(self, model, data, epochs, context_length, batch_size, lr):\n        optimizer = torch.optim.AdamW(model.parameters(), lr=lr)\n        final_loss = 0.0\n        for epoch in range(epochs):\n            torch.manual_seed(epoch)\n            starts = torch.randint(0, len(data) - context_length, (batch_size,))\n            X = torch.stack([data[s:s+context_length] for s in starts])\n            Y = torch.stack([data[s+1:s+1+context_length] for s in starts])\n            logits = model(X)\n            B, T, C = logits.shape\n            logits_flat = logits.reshape(B*T, C)\n            targets_flat = Y.reshape(B*T)\n            loss = F.cross_entropy(logits_flat, targets_flat)\n            optimizer.zero_grad()\n            loss.backward()\n            optimizer.step()\n            final_loss = loss.item()\n        return round(final_loss, 4)")